package io.forgeloop.control.domain;
import jakarta.persistence.*;import java.util.*;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"organization_id","name"})) public class HarnessDefinition{
 @Id @GeneratedValue(strategy=GenerationType.UUID)private String id;@Column(nullable=false)private String organizationId;@Column(nullable=false,length=80)private String name;@Column(nullable=false,length=1000)private String description;@Column(nullable=false,length=1000)private String allowedRoles;private int defaultAttemptBudget;private boolean enabled;private int revision;
 protected HarnessDefinition(){}public HarnessDefinition(String org,String name,String description,List<String> roles,int attempts){if(org==null||org.isBlank()||name==null||!name.matches("[A-Z][A-Z0-9_-]{1,79}")||description==null||description.isBlank()||roles==null||roles.isEmpty()||attempts<1||attempts>10)throw new IllegalArgumentException("Harness definition is invalid");this.organizationId=org;this.name=name;this.description=description;this.allowedRoles=String.join(",",new LinkedHashSet<>(roles));this.defaultAttemptBudget=attempts;enabled=true;revision=1;}
 public boolean belongsTo(String org){return organizationId.equals(org);}public String getId(){return id;}public String getOrganizationId(){return organizationId;}public String getName(){return name;}public String getDescription(){return description;}public List<String> getAllowedRoles(){return Arrays.stream(allowedRoles.split(",")).toList();}public int getDefaultAttemptBudget(){return defaultAttemptBudget;}public boolean isEnabled(){return enabled;}public int getRevision(){return revision;}
}
